code_example:
typedef struct {
    int key;
    int value;
} Entry;

typedef struct {
    Entry *entries;
    size_t size;
    void *(*subscript)(struct Map *, const void *key);
} Map;

// Function implementing subscript behavior
void *map_subscript(Map *map, const void *key) {
    const Entry *entries = map->entries;
    for (size_t i = 0; i < map->size; ++i) {
        if (entries[i].key == *(int *)key) {
            return &entries[i].value;
        }
    }
    return NULL; // key not found
}

// Usage example
int main() {
    Entry data[] = {{1, 100}, {2, 200}, {3, 300}};
    Map myMap = { data, 3, map_subscript };
    int key = 2;
    int *value_ptr = (int *)myMap.subscript(&myMap, &key);
    if (value_ptr) {
        // Access the value
        printf("Value: %d\n", *value_ptr);
    }
    return 0;
}
